script:
(async function () {
  const modules = await Promise.all([
    import("https://esm.sh/@tiptap/core@2.2.4"),
    import("https://esm.sh/@tiptap/extension-placeholder@2.2.4"),
    import("https://esm.sh/@tiptap/starter-kit@2.2.4"),
    import("https://esm.sh/@tiptap/extension-link@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-align@2.2.4"),
    import("https://esm.sh/@tiptap/extension-image@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-list@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-item@2.2.4"),
    import("https://esm.sh/@tiptap/extension-color@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-style@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-row@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-cell@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-header@2.2.4"),
  ]).catch((err) => {
    console.error("Error loading Tiptap extensions:", err);
    return null;
  });
  if (!modules) return;

  const [
    { Editor, mergeAttributes, Node },
    { Placeholder },
    { default: StarterKit },
    { Link },
    { TextAlign },
    { Image },
    { TaskList },
    { TaskItem },
    { Color },
    { TextStyle },
    { Table },
    { TableRow },
    { TableCell },
    { TableHeader },
  ] = modules;

  // File Upload Helpers

  function fileToBase64(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === "string") resolve(reader.result);
        else reject(new Error("Unexpected FileReader result type"));
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  function getPostName() {
    if (window.cafePostName) return window.cafePostName;
    const pathMatch = window.location.pathname.match(/\/edit-post\/([^/]+)/);
    if (pathMatch) return decodeURIComponent(pathMatch[1]);
    return new URLSearchParams(window.location.search).get("name") || null;
  }

  async function uploadFile(file, options = {}) {
    return new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      const formData = new FormData();

      formData.append("file", file, file.name);
      formData.append("is_private", options.private ? "1" : "0");
      formData.append("folder", options.folder || "Home");
      if (options.doctype) formData.append("doctype", options.doctype);
      if (options.docname) formData.append("docname", options.docname);
      if (options.fieldname) formData.append("fieldname", options.fieldname);

      xhr.open(
        "POST",
        options.uploadEndpoint || "/api/method/upload_file",
        true,
      );
      xhr.setRequestHeader("Accept", "application/json");

      const csrfToken = window.csrf_token || window.frappe?.csrf_token;
      if (csrfToken && csrfToken !== "{{ csrf_token }}") {
        xhr.setRequestHeader("X-Frappe-CSRF-Token", csrfToken);
      }

      xhr.onreadystatechange = () => {
        if (xhr.readyState !== XMLHttpRequest.DONE) return;
        if (xhr.status === 200) {
          let r;
          try {
            r = JSON.parse(xhr.responseText);
          } catch {
            r = xhr.responseText;
          }
          resolve(r.message || r);
        } else {
          let error = "Upload failed";
          try {
            const err = JSON.parse(xhr.responseText);
            error = err._error_message || err.message || error;
          } catch {
            // use default error message
          }
          reject(new Error(error));
        }
      };

      xhr.onerror = () => reject(new Error("Network error during upload"));
      xhr.send(formData);
    });
  }

  const uploadMap = new Map();

  function generateUploadId() {
    return `upload-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }

  function updateNodeInView(view, nodeType, uploadId, newAttrs) {
    view.state.doc.descendants((node, pos) => {
      if (node.type.name === nodeType && node.attrs.uploadId === uploadId) {
        view.dispatch(
          view.state.tr.setNodeMarkup(pos, undefined, {
            ...node.attrs,
            ...newAttrs,
          }),
        );
        return false;
      }
    });
  }

  async function retryMediaUpload(view, nodeType, uploadId, file) {
    updateNodeInView(view, nodeType, uploadId, { loading: true, error: null });
    try {
      const result = await uploadFile(file, {
        doctype: "Cafe Post",
        docname: getPostName(),
        fieldname: "content",
      });
      updateNodeInView(view, nodeType, uploadId, {
        src: result.file_url,
        loading: false,
        error: null,
      });
      uploadMap.delete(uploadId);
    } catch (error) {
      updateNodeInView(view, nodeType, uploadId, {
        loading: false,
        error: error.message || `Failed to upload ${nodeType}`,
      });
    }
  }

  function getVideoDimensions(src) {
    return new Promise((resolve, reject) => {
      const video = document.createElement("video");
      video.preload = "metadata";
      video.onloadedmetadata = () => {
        resolve({ width: video.videoWidth, height: video.videoHeight });
        video.src = "";
      };
      video.onerror = reject;
      video.src = src;
    });
  }

  async function uploadAndInsertMedia(file, type, view, pos = null) {
    const uploadId = generateUploadId();
    let previewSrc;
    let extraAttrs = {};
    let objectUrl = null;

    if (type === "image") {
      previewSrc = await fileToBase64(file);
    } else {
      objectUrl = URL.createObjectURL(file);
      const dimensions = await getVideoDimensions(objectUrl).catch(() => ({
        width: null,
        height: null,
      }));
      previewSrc = objectUrl;
      extraAttrs = { width: dimensions.width, height: dimensions.height };
    }

    uploadMap.set(uploadId, { file });
    const insertPos = pos != null ? pos : view.state.tr.selection.from;
    const node = view.state.schema.nodes[type].create({
      src: previewSrc,
      uploadId,
      loading: true,
      ...extraAttrs,
    });
    view.dispatch(view.state.tr.insert(insertPos, node));

    try {
      const result = await uploadFile(file, {
        doctype: "Cafe Post",
        docname: getPostName(),
        fieldname: "content",
      });
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      updateNodeInView(view, type, uploadId, {
        src: result.file_url,
        loading: false,
      });
      uploadMap.delete(uploadId);
    } catch (error) {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      updateNodeInView(view, type, uploadId, {
        loading: false,
        error: error.message || `Failed to upload ${type}`,
      });
      uploadMap.delete(uploadId);
    }
  }

  // Custom Extensions

  const SHARED_MEDIA_ATTRS = {
    src: { default: null },
    alt: { default: null },
    title: { default: null },
    width: { default: null },
    height: { default: null },
    uploadId: { default: null },
    loading: { default: false },
    error: { default: null },
  };

  function buildUploadDataAttrs({ uploadId, loading, error }) {
    const attrs = {};
    if (uploadId) attrs["data-upload-id"] = uploadId;
    if (loading) attrs["data-loading"] = "true";
    if (error) attrs["data-error"] = error;
    return attrs;
  }

  const CustomImage = Image.extend({
    addAttributes() {
      return { ...SHARED_MEDIA_ATTRS };
    },
    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      return [
        "img",
        mergeAttributes(
          this.options.HTMLAttributes || {},
          rest,
          buildUploadDataAttrs({ uploadId, loading, error }),
        ),
      ];
    },
  });

  const CustomVideo = Node.create({
    name: "video",
    group: "block",
    selectable: true,
    draggable: true,
    atom: true,

    addAttributes() {
      return {
        ...SHARED_MEDIA_ATTRS,
        autoplay: { default: false },
        loop: { default: false },
        muted: { default: false },
      };
    },

    parseHTML() {
      return [
        {
          tag: "video",
          getAttrs: (node) => {
            if (typeof node === "string") return {};
            return {
              src: node.getAttribute("src"),
              alt: node.getAttribute("alt"),
              title: node.getAttribute("title"),
              width: node.getAttribute("width"),
              height: node.getAttribute("height"),
              autoplay: node.hasAttribute("autoplay"),
              loop: node.hasAttribute("loop"),
              muted: node.hasAttribute("muted"),
            };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      return [
        "video",
        mergeAttributes(
          this.options.HTMLAttributes || {},
          rest,
          buildUploadDataAttrs({ uploadId, loading, error }),
          { controls: "" },
        ),
      ];
    },
  });

  const editorElement = document.getElementById("editor");
  if (!editorElement) return;

  if (!document.getElementById("tiptap-placeholder-css")) {
    const style = document.createElement("style");
    style.id = "tiptap-placeholder-css";
    style.innerHTML = `
      .tiptap p.is-editor-empty:first-child::before {
        color: #adb5bd;
        content: attr(data-placeholder);
        float: left;
        height: 0;
        pointer-events: none;
      }
    `;
    document.head.appendChild(style);
  }

  const toolbarHTML = `
    <div id="editor-toolbar">
      <div class="tb-group">
        <button class="tb-btn" data-action="p" title="Paragraph">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="4 7 4 4 20 4 20 7"></polyline><line x1="9" y1="20" x2="15" y2="20"></line><line x1="12" y1="4" x2="12" y2="20"></line></svg>
        </button>
        <div class="tb-dropdown-container" id="heading-dropdown">
          <button class="tb-btn" id="heading-btn" title="Heading">
            <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M7 12h10"></path><path d="M7 5v14"></path><path d="M17 5v14"></path></svg>
          </button>
          <div class="tb-dropdown-menu" id="heading-menu">
            <button class="tb-btn tb-menu-item" data-action="h1">H1</button>
            <button class="tb-btn tb-menu-item" data-action="h2">H2</button>
            <button class="tb-btn tb-menu-item" data-action="h3">H3</button>
            <button class="tb-btn tb-menu-item" data-action="h4">H4</button>
            <button class="tb-btn tb-menu-item" data-action="h5">H5</button>
            <button class="tb-btn tb-menu-item" data-action="h6">H6</button>
          </div>
        </div>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="bold" title="Bold">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 4h8a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path><path d="M6 12h9a4 4 0 0 1 4 4 4 4 0 0 1-4 4H6z"></path></svg>
        </button>
        <button class="tb-btn" data-action="italic" title="Italic">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="19" y1="4" x2="10" y2="4"></line><line x1="14" y1="20" x2="5" y2="20"></line><line x1="15" y1="4" x2="9" y2="20"></line></svg>
        </button>
        <button class="tb-btn" data-action="strike" title="Strikethrough">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line><path d="M16 6C16 6 14.745 4 12 4 9.255 4 8 6 8 6"></path><path d="M8 18c0 0 1.255 2 4 2 2.745 0 4-2 4-2"></path></svg>
        </button>
        <button class="tb-btn" data-action="link" title="Link">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71"></path><path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"></path></svg>
        </button>
        <button class="tb-btn" data-action="color" title="Font Color">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20"></path><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path></svg>
        </button>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="bulletList" title="Bullet List">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="8" y1="6" x2="21" y2="6"></line><line x1="8" y1="12" x2="21" y2="12"></line><line x1="8" y1="18" x2="21" y2="18"></line><line x1="3" y1="6" x2="3.01" y2="6"></line><line x1="3" y1="12" x2="3.01" y2="12"></line><line x1="3" y1="18" x2="3.01" y2="18"></line></svg>
        </button>
        <button class="tb-btn" data-action="orderedList" title="Numbered List">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="10" y1="6" x2="21" y2="6"></line><line x1="10" y1="12" x2="21" y2="12"></line><line x1="10" y1="18" x2="21" y2="18"></line><path d="M4 6h1v4"></path><path d="M4 10h2"></path><path d="M6 18H4c0-1 2-2 2-3s-1-1.5-2-1"></path></svg>
        </button>
        <button class="tb-btn" data-action="taskList" title="Task List">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"></path><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"></path></svg>
        </button>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="alignLeft" title="Align Left">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="17" y1="10" x2="3" y2="10"></line><line x1="21" y1="6" x2="3" y2="6"></line><line x1="21" y1="14" x2="3" y2="14"></line><line x1="17" y1="18" x2="3" y2="18"></line></svg>
        </button>
        <button class="tb-btn" data-action="alignCenter" title="Align Center">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="10" x2="6" y2="10"></line><line x1="21" y1="6" x2="3" y2="6"></line><line x1="21" y1="14" x2="3" y2="14"></line><line x1="18" y1="18" x2="6" y2="18"></line></svg>
        </button>
        <button class="tb-btn" data-action="alignRight" title="Align Right">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="21" y1="10" x2="7" y2="10"></line><line x1="21" y1="6" x2="3" y2="6"></line><line x1="21" y1="14" x2="3" y2="14"></line><line x1="21" y1="18" x2="7" y2="18"></line></svg>
        </button>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="image" title="Image">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><circle cx="8.5" cy="8.5" r="1.5"></circle><polyline points="21 15 16 10 5 21"></polyline></svg>
        </button>
        <button class="tb-btn" data-action="video" title="Video">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polygon points="23 7 16 12 23 17 23 7"></polygon><rect x="1" y="5" width="15" height="14" rx="2" ry="2"></rect></svg>
        </button>
        <button class="tb-btn" data-action="blockquote" title="Blockquote">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M10 11h-4a1 1 0 0 1 -1 -1v-3a1 1 0 0 1 1 -1h3a1 1 0 0 1 1 1v6c0 2.667 -1.333 4.333 -4 5"></path><path d="M19 11h-4a1 1 0 0 1 -1 -1v-3a1 1 0 0 1 1 -1h3a1 1 0 0 1 1 1v6c0 2.667 -1.333 4.333 -4 5"></path></svg>
        </button>
        <button class="tb-btn" data-action="code" title="Code">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="16 18 22 12 16 6"></polyline><polyline points="8 6 2 12 8 18"></polyline></svg>
        </button>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="hr" title="Horizontal Rule">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="5" y1="12" x2="19" y2="12"></line></svg>
        </button>

        <div class="tb-dropdown-container" id="table-dropdown">
          <button class="tb-btn" id="table-btn" title="Table">
            <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect><line x1="3" y1="9" x2="21" y2="9"></line><line x1="3" y1="15" x2="21" y2="15"></line><line x1="9" y1="3" x2="9" y2="21"></line><line x1="15" y1="3" x2="15" y2="21"></line></svg>
          </button>
          <div class="tb-dropdown-menu" id="table-menu">
            <button class="tb-btn tb-menu-item" data-action="insertTable">Insert Table</button>
            <button class="tb-btn tb-menu-item" data-action="addColumnBefore">Add Column Before</button>
            <button class="tb-btn tb-menu-item" data-action="addColumnAfter">Add Column After</button>
            <button class="tb-btn tb-menu-item" data-action="deleteColumn">Delete Column</button>
            <button class="tb-btn tb-menu-item" data-action="addRowBefore">Add Row Before</button>
            <button class="tb-btn tb-menu-item" data-action="addRowAfter">Add Row After</button>
            <button class="tb-btn tb-menu-item" data-action="deleteRow">Delete Row</button>
            <button class="tb-btn tb-menu-item" data-action="mergeCells">Merge Cells</button>
            <button class="tb-btn tb-menu-item" data-action="splitCell">Split Cell</button>
            <button class="tb-btn tb-menu-item" data-action="toggleHeaderColumn">Toggle Header Column</button>
            <button class="tb-btn tb-menu-item" data-action="toggleHeaderRow">Toggle Header Row</button>
            <button class="tb-btn tb-menu-item" data-action="toggleHeaderCell">Toggle Header Cell</button>
            <button class="tb-btn tb-menu-item" data-action="deleteTable">Delete Table</button>
          </div>
        </div>

        <div class="tb-separator"></div>

        <button class="tb-btn" data-action="undo" title="Undo">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="1 4 1 10 7 10"></polyline><path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"></path></svg>
        </button>
        <button class="tb-btn" data-action="redo" title="Redo">
          <svg class="tb-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"></polyline><path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10"></path></svg>
        </button>
      </div>
    </div>
  `;

  const editPostWrapper = document.getElementById("edit-post-wrapper");
  if (editPostWrapper) {
    editPostWrapper.insertAdjacentHTML("afterbegin", toolbarHTML);
  } else {
    editorElement.insertAdjacentHTML("beforebegin", toolbarHTML);
  }

  const btns = document.querySelectorAll(".tb-btn");

  const ACTIVE_CHECKS = {
    bold: (e) => e.isActive("bold"),
    italic: (e) => e.isActive("italic"),
    strike: (e) => e.isActive("strike"),
    p: (e) => e.isActive("paragraph"),
    bulletList: (e) => e.isActive("bulletList"),
    orderedList: (e) => e.isActive("orderedList"),
    taskList: (e) => e.isActive("taskList"),
    blockquote: (e) => e.isActive("blockquote"),
    code: (e) => e.isActive("code"),
    link: (e) => e.isActive("link"),
    h1: (e) => e.isActive("heading", { level: 1 }),
    h2: (e) => e.isActive("heading", { level: 2 }),
    h3: (e) => e.isActive("heading", { level: 3 }),
    h4: (e) => e.isActive("heading", { level: 4 }),
    h5: (e) => e.isActive("heading", { level: 5 }),
    h6: (e) => e.isActive("heading", { level: 6 }),
    alignLeft: (e) => e.isActive({ textAlign: "left" }),
    alignCenter: (e) => e.isActive({ textAlign: "center" }),
    alignRight: (e) => e.isActive({ textAlign: "right" }),
  };

  const editor = new Editor({
    element: editorElement,
    extensions: [
      StarterKit,
      Placeholder.configure({ placeholder: "Write your story..." }),
      Link,
      TextAlign.configure({ types: ["heading", "paragraph"] }),
      CustomImage,
      CustomVideo,
      TaskList,
      TaskItem,
      TextStyle,
      Color,
      Table.configure({ resizable: true }),
      TableRow,
      TableHeader,
      TableCell,
    ],
    editorProps: {
      attributes: {
        class:
          "prose prose-sm sm:prose lg:prose-lg xl:prose-2xl mx-auto focus:outline-none",
        style: "min-height: 85%; border: 0; outline: none;",
      },
      handleDOMEvents: {
        drop(view, event) {
          const hasFiles = event.dataTransfer?.files?.length;
          if (!hasFiles) return false;

          const files = Array.from(event.dataTransfer.files);
          const images = files.filter((f) => f.type.startsWith("image/"));
          const videos = files.filter((f) => f.type.startsWith("video/"));
          if (images.length === 0 && videos.length === 0) return false;

          event.preventDefault();
          const coordinates = view.posAtCoords({
            left: event.clientX,
            top: event.clientY,
          });
          const pos = coordinates ? coordinates.pos : view.state.selection.from;
          images.forEach((file) =>
            uploadAndInsertMedia(file, "image", view, pos),
          );
          videos.forEach((file) =>
            uploadAndInsertMedia(file, "video", view, pos),
          );
          return true;
        },
        paste(view, event) {
          const items = event.clipboardData?.items;
          if (!items) return false;

          const images = [];
          const videos = [];
          for (const item of items) {
            if (item.kind !== "file") continue;
            const file = item.getAsFile();
            if (!file) continue;
            if (item.type.startsWith("image/")) images.push(file);
            else if (item.type.startsWith("video/")) videos.push(file);
          }

          if (images.length === 0 && videos.length === 0) return false;
          event.preventDefault();
          images.forEach((file) => uploadAndInsertMedia(file, "image", view));
          videos.forEach((file) => uploadAndInsertMedia(file, "video", view));
          return true;
        },
        click(view, event) {
          const target = event.target;
          const isFailedMedia =
            (target.tagName === "IMG" || target.tagName === "VIDEO") &&
            target.dataset.error;
          if (!isFailedMedia) return false;

          const nodeType = target.tagName === "IMG" ? "image" : "video";
          const uploadId = target.dataset.uploadId;
          const fileData = uploadMap.get(uploadId);
          if (!fileData) return false;

          event.preventDefault();
          retryMediaUpload(view, nodeType, uploadId, fileData.file);
          return true;
        },
      },
    },
    onTransaction: ({ editor }) => {
      btns.forEach((btn) => {
        const check = ACTIVE_CHECKS[btn.dataset.action];
        btn.classList.toggle("is-active", check ? check(editor) : false);
      });
    },
  });

  const headingBtn = document.getElementById("heading-btn");
  const headingMenu = document.getElementById("heading-menu");
  if (headingBtn && headingMenu) {
    headingBtn.addEventListener("click", (e) => {
      e.preventDefault();
      headingMenu.classList.toggle("is-open");
    });
  }

  const tableBtn = document.getElementById("table-btn");
  const tableMenu = document.getElementById("table-menu");
  if (tableBtn && tableMenu) {
    tableBtn.addEventListener("click", (e) => {
      e.preventDefault();
      tableMenu.classList.toggle("is-open");
    });
  }

  document.addEventListener("click", (e) => {
    if (
      headingBtn &&
      headingMenu &&
      !headingBtn.contains(e.target) &&
      !headingMenu.contains(e.target)
    ) {
      headingMenu.classList.remove("is-open");
    }
    if (
      tableBtn &&
      tableMenu &&
      !tableBtn.contains(e.target) &&
      !tableMenu.contains(e.target)
    ) {
      tableMenu.classList.remove("is-open");
    }
  });

  if (tableMenu) {
    tableMenu.querySelectorAll("button").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        const action = btn.dataset.action;
        if (action === "insertTable") {
          editor
            .chain()
            .focus()
            .insertTable({ rows: 3, cols: 3, withHeaderRow: true })
            .run();
        } else {
          editor.chain().focus()[action]?.().run();
        }
        tableMenu.classList.remove("is-open");
      });
    });
  }

  btns.forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const action = btn.dataset.action;

      const hMatch = action?.match(/^h([1-6])$/);
      if (hMatch) {
        editor
          .chain()
          .focus()
          .toggleHeading({ level: parseInt(hMatch[1], 10) })
          .run();
        headingMenu?.classList.remove("is-open");
        return;
      }

      switch (action) {
        case "bold":
          editor.chain().focus().toggleBold().run();
          break;
        case "italic":
          editor.chain().focus().toggleItalic().run();
          break;
        case "strike":
          editor.chain().focus().toggleStrike().run();
          break;
        case "p":
          editor.chain().focus().setParagraph().run();
          break;
        case "bulletList":
          editor.chain().focus().toggleBulletList().run();
          break;
        case "orderedList":
          editor.chain().focus().toggleOrderedList().run();
          break;
        case "taskList":
          editor.chain().focus().toggleTaskList().run();
          break;
        case "alignLeft":
          editor.chain().focus().setTextAlign("left").run();
          break;
        case "alignCenter":
          editor.chain().focus().setTextAlign("center").run();
          break;
        case "alignRight":
          editor.chain().focus().setTextAlign("right").run();
          break;
        case "blockquote":
          editor.chain().focus().toggleBlockquote().run();
          break;
        case "code":
          editor.chain().focus().toggleCode().run();
          break;
        case "hr":
          editor.chain().focus().setHorizontalRule().run();
          break;
        case "undo":
          editor.chain().focus().undo().run();
          break;
        case "redo":
          editor.chain().focus().redo().run();
          break;
        case "link": {
          const url = window.prompt("URL");
          if (url)
            editor
              .chain()
              .focus()
              .extendMarkRange("link")
              .setLink({ href: url })
              .run();
          else if (url === "")
            editor.chain().focus().extendMarkRange("link").unsetLink().run();
          break;
        }
        case "color": {
          const color = window.prompt(
            "Color (e.g., #ff0000 or red)",
            "#000000",
          );
          if (color) editor.chain().focus().setColor(color).run();
          break;
        }
        case "image":
        case "video": {
          const input = document.createElement("input");
          input.type = "file";
          input.accept = `${action}/*`;
          input.multiple = true;
          input.onchange = ({ target }) => {
            if (target.files?.length) {
              Array.from(target.files).forEach((file) =>
                uploadAndInsertMedia(file, action, editor.view),
              );
            }
          };
          input.click();
          break;
        }
      }
    });
  });

  const navbarActionButtons = document.getElementById("navbar-action-buttons");
  if (navbarActionButtons) {
    navbarActionButtons.innerHTML = "";
    const publishBtn = document.createElement("button");
    publishBtn.id = "publish-post";
    publishBtn.textContent = "Publish";
    publishBtn.style.cssText =
      "background-color: #1a1a1a; color: #ffffff; border: none; border-radius: 8px; padding: 4px 10px; font-size: 13px;";
    publishBtn.addEventListener("click", (e) => {
      e.preventDefault();
      // TODO: Implement the publish API call here using window.frappeClient.post()
    });
    navbarActionButtons.appendChild(publishBtn);
  }

  // Tags

  const tagsContainer =
    document.querySelector("#tags-container") ||
    document.querySelector(".tags-container");
  if (tagsContainer) {
    const selectedTags = new Set();

    const inputWrapper = document.createElement("div");
    inputWrapper.className = "tag-input-wrapper";

    const input = document.createElement("input");
    input.type = "text";
    input.className = "tag-search-input";
    input.placeholder = "Add tags…";
    input.style.padding = 0;

    const dropdown = document.createElement("div");
    dropdown.className = "tag-dropdown";

    inputWrapper.appendChild(input);
    inputWrapper.appendChild(dropdown);
    tagsContainer.appendChild(inputWrapper);

    function renderChips() {
      tagsContainer.querySelectorAll(".tag-chip").forEach((el) => el.remove());
      selectedTags.forEach((name) => {
        const chip = document.createElement("span");
        chip.className = "tag-chip";
        chip.innerHTML = `${name}<span class="tag-remove" data-tag="${name}">×</span>`;
        tagsContainer.insertBefore(chip, inputWrapper);
      });
    }

    function renderDropdown(query) {
      const tags = (window.page_data && window.page_data.tags) || [];
      const filtered = tags
        .map((t) => t.name)
        .filter(
          (n) =>
            !selectedTags.has(n) &&
            n.toLowerCase().includes(query.toLowerCase()),
        );

      dropdown.innerHTML = "";
      if (filtered.length === 0) {
        const opt = document.createElement("div");
        opt.className = "tag-option no-results";
        opt.textContent = "No tags found";
        dropdown.appendChild(opt);
      } else {
        filtered.forEach((name) => {
          const opt = document.createElement("div");
          opt.className = "tag-option";
          opt.textContent = name;
          opt.addEventListener("mousedown", (e) => {
            e.preventDefault();
            if (selectedTags.size >= 3) return;
            selectedTags.add(name);
            input.value = "";
            renderChips();
            renderDropdown(input.value);
            if (selectedTags.size >= 3) {
              dropdown.classList.remove("is-open");
              input.placeholder = "";
              input.disabled = true;
            }
          });
          dropdown.appendChild(opt);
        });
      }
    }

    input.addEventListener("focus", () => {
      renderDropdown(input.value);
      dropdown.classList.add("is-open");
    });

    input.addEventListener("input", () => {
      renderDropdown(input.value);
      dropdown.classList.add("is-open");
    });

    input.addEventListener("blur", () => {
      setTimeout(() => dropdown.classList.remove("is-open"), 150);
    });

    tagsContainer.addEventListener("click", (e) => {
      if (e.target.classList.contains("tag-remove")) {
        selectedTags.delete(e.target.dataset.tag);
        input.disabled = false;
        input.placeholder = "Add tags…";
        renderChips();
      }
    });

    window.getSelectedTags = () => Array.from(selectedTags);
  }
})();
